package com.kongye.floatball;
import android.graphics.*;
import com.google.android.gms.tasks.Tasks;
import com.google.mlkit.vision.common.InputImage;
import com.google.mlkit.vision.text.*;
import com.google.mlkit.vision.text.chinese.ChineseTextRecognizerOptions;
import java.util.*;
import java.util.function.BooleanSupplier;

/** Original-resolution, overlapping tiles. Low-confidence tiles get a second, enlarged contrast pass. */
final class OcrPipeline {
 static final class Line {
  String text;final Rect box;final float confidence;java.util.List<TextRegion> parts;
  Line(Text.Line line,int x,int y,float scale){text=line.getText();box=map(line.getBoundingBox(),x,y,scale);confidence=line.getConfidence();parts=new ArrayList<>();for(Text.Element e:line.getElements()){Rect b=map(e.getBoundingBox(),x,y,scale);ArrayList<TextRegion> symbols=new ArrayList<>();for(Text.Symbol symbol:e.getSymbols()){Rect sb=map(symbol.getBoundingBox(),x,y,scale);symbols.add(region(symbol.getText(),sb,Collections.emptyList()));}parts.add(new TextRegion(e.getText(),b.left,b.top,b.right,b.bottom,symbols,true));}}
  TextRegion region(){return new TextRegion(text,box.left,box.top,box.right,box.bottom,parts,false,confidence);}
  private static Rect map(Rect b,int x,int y,float scale){return b==null?new Rect():new Rect(x+Math.round(b.left/scale),y+Math.round(b.top/scale),x+Math.round(b.right/scale),y+Math.round(b.bottom/scale));}
  private static TextRegion region(String text,Rect b,List<TextRegion> parts){return new TextRegion(text,b.left,b.top,b.right,b.bottom,parts);}
 }

 static float score(Text text){float sum=0;int count=0;for(Text.TextBlock b:text.getTextBlocks())for(Text.Line l:b.getLines()){int n=l.getText().length();sum+=l.getConfidence()*n;count+=n;}return count==0?0:sum/count;}
 static String recognize(Bitmap source,BooleanSupplier cancelled)throws Exception{
  return recognize(source,cancelled,null);}
 static String recognize(Bitmap source,BooleanSupplier cancelled,java.util.function.Consumer<String> diagnostic)throws Exception{return RegionTextFusion.text(recognizeRegions(source,cancelled,diagnostic));}
 static java.util.List<TextRegion> recognizeRegions(Bitmap source,BooleanSupplier cancelled)throws Exception{return recognizeRegions(source,cancelled,null);}
 private static java.util.List<TextRegion> recognizeRegions(Bitmap source,BooleanSupplier cancelled,java.util.function.Consumer<String> diagnostic)throws Exception{TextRecognizer reader=TextRecognition.getClient(new ChineseTextRecognizerOptions.Builder().build());ArrayList<Line> lines=new ArrayList<>();
  try{int step=1280,overlap=96;for(int top=0;top<source.getHeight();top+=step)for(int left=0;left<source.getWidth();left+=step){if(cancelled.getAsBoolean())throw new java.io.InterruptedIOException();int x=Math.max(0,left-overlap),y=Math.max(0,top-overlap),right=Math.min(source.getWidth(),left+step+overlap),bottom=Math.min(source.getHeight(),top+step+overlap);Bitmap tile=Bitmap.createBitmap(source,x,y,right-x,bottom-y);boolean own=tile!=source;try{Text first=Tasks.await(reader.process(InputImage.fromBitmap(tile,0)),30,java.util.concurrent.TimeUnit.SECONDS);if(diagnostic!=null)diagnostic.accept("original="+first.getText()+" score="+score(first));Text chosen=first;float scale=1;float firstScore=score(first);boolean tiny=false;for(Text.TextBlock b:first.getTextBlocks())for(Text.Line l:b.getLines())if(l.getBoundingBox()!=null&&l.getBoundingBox().height()<22)tiny=true;
   if(firstScore<.83f||tiny||first.getText().isEmpty()){float factor=tile.getWidth()*tile.getHeight()<=1100000?2:1.5f;Bitmap enlarged=Bitmap.createBitmap(Math.round(tile.getWidth()*factor),Math.round(tile.getHeight()*factor),Bitmap.Config.ARGB_8888);try{Canvas canvas=new Canvas(enlarged);Paint paint=new Paint(3);long light=0;int samples=0;for(int yy=0;yy<tile.getHeight();yy+=32)for(int xx=0;xx<tile.getWidth();xx+=32){int c=tile.getPixel(xx,yy);light+=(Color.red(c)*299+Color.green(c)*587+Color.blue(c)*114)/1000;samples++;}boolean dark=light/Math.max(1,samples)<125;ColorMatrix matrix=new ColorMatrix(new float[]{.299f,.587f,.114f,0,0,.299f,.587f,.114f,0,0,.299f,.587f,.114f,0,0,0,0,0,1,0});float contrast=dark?-1.15f:1.15f,offset=dark?274:-19;matrix.postConcat(new ColorMatrix(new float[]{contrast,0,0,0,offset,0,contrast,0,0,offset,0,0,contrast,0,offset,0,0,0,1,0}));paint.setColorFilter(new ColorMatrixColorFilter(matrix));canvas.drawBitmap(tile,null,new Rect(0,0,enlarged.getWidth(),enlarged.getHeight()),paint);Text second=Tasks.await(reader.process(InputImage.fromBitmap(enlarged,0)),30,java.util.concurrent.TimeUnit.SECONDS);if(diagnostic!=null)diagnostic.accept("enhanced="+second.getText()+" score="+score(second));if(!second.getText().isEmpty()&&(first.getText().isEmpty()||score(second)>firstScore+.02f)){chosen=second;scale=factor;}}finally{enlarged.recycle();}}
   int refinedCount=0;for(Text.TextBlock block:chosen.getTextBlocks())for(Text.Line l:block.getLines()){if(cancelled.getAsBoolean())throw new java.io.InterruptedIOException();Line line=new Line(l,x,y,scale);if(l.getConfidence()<.85f&&refinedCount++<6&&line.box.width()>0&&line.box.height()>0){Rect bounds=new Rect(Math.max(0,line.box.left-x-4),Math.max(0,line.box.top-y-4),Math.min(tile.getWidth(),line.box.right-x+4),Math.min(tile.getHeight(),line.box.bottom-y+4));if(bounds.width()>0&&bounds.height()>0&&bounds.width()*bounds.height()<500000){Bitmap detail=Bitmap.createBitmap(bounds.width()*2+32,bounds.height()*2+32,Bitmap.Config.ARGB_8888);try{detail.eraseColor(tile.getPixel(bounds.left,bounds.top));new Canvas(detail).drawBitmap(tile,bounds,new Rect(16,16,detail.getWidth()-16,detail.getHeight()-16),new Paint(3));Text refined=Tasks.await(reader.process(InputImage.fromBitmap(detail,0)),30,java.util.concurrent.TimeUnit.SECONDS);if(diagnostic!=null)diagnostic.accept("line="+refined.getText()+" score="+score(refined));if(!refined.getText().isBlank()&&score(refined)>l.getConfidence()+.12f){line.text=refined.getText().replace('\n',' ');ArrayList<TextRegion> detailParts=new ArrayList<>();for(Text.TextBlock rb:refined.getTextBlocks())for(Text.Line rl:rb.getLines())detailParts.add(new Line(rl,x+bounds.left-8,y+bounds.top-8,2).region());line.parts=detailParts;}}finally{detail.recycle();}}}if(line.box.centerX()>=left&&line.box.centerX()<left+step&&line.box.centerY()>=top&&line.box.centerY()<top+step)lines.add(line);}
  }finally{if(own)tile.recycle();}}
  if(cancelled.getAsBoolean())throw new java.io.InterruptedIOException();
  // A page-scale pass provides context; use it only when its line confidence beats the detail pass.
  if(Math.max(source.getWidth(),source.getHeight())>1536){float scale=Math.min(1f,2048f/Math.max(source.getWidth(),source.getHeight()));Bitmap overview=Bitmap.createScaledBitmap(source,Math.max(1,Math.round(source.getWidth()*scale)),Math.max(1,Math.round(source.getHeight()*scale)),true);try{Text whole=Tasks.await(reader.process(InputImage.fromBitmap(overview,0)),30,java.util.concurrent.TimeUnit.SECONDS);for(Text.TextBlock block:whole.getTextBlocks())for(Text.Line l:block.getLines()){Line candidate=new Line(l,0,0,scale);Line matched=null;for(Line line:lines)if(Math.abs(line.box.centerY()-candidate.box.centerY())<Math.max(line.box.height(),candidate.box.height())/2&&Rect.intersects(line.box,candidate.box)){matched=line;break;}if(matched==null){if(candidate.confidence>.6f)lines.add(candidate);}else if(candidate.confidence>matched.confidence+.03f){matched.text=candidate.text;matched.parts=candidate.parts;}}}finally{if(overview!=source)overview.recycle();}}
  ArrayList<TextRegion> regions=new ArrayList<>();for(Line line:lines)regions.add(line.region());return regions;
  }finally{reader.close();}
 }
}
